(() => {
'use strict';
const $=id=>document.getElementById(id),key='daily-desk-v1';
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
let state={expenses:[],sessions:[],currency:'INR',goal:120},editingTransaction=null;
const opening=()=>state.opening||null;
const incomes=()=>state.incomes||[];
const round=n=>Math.round((n+Number.EPSILON)*100)/100;
const balanceBefore=date=>round(state.opening.amount+sum(incomes().filter(x=>x.date>=state.opening.date&&x.date<date),'amount')-sum(state.expenses.filter(x=>x.date>=state.opening.date&&x.date<date),'amount'));
function download(blob,name){const u=URL.createObjectURL(blob),a=node('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function valid(s){return s&&(!s.customCategories||['income','expense'].every(type=>Array.isArray(s.customCategories[type])&&s.customCategories[type].length<=100&&s.customCategories[type].every(x=>typeof x==='string'&&x.trim().length>0&&x.length<=60)))&&[...(s.expenses||[]),...(s.incomes||[])].every(x=>x&&(x.remark===undefined||(typeof x.remark==='string'&&x.remark.length<=500)))&&(s.incomes===undefined||(Array.isArray(s.incomes)&&s.incomes.length<=50000&&s.incomes.every(x=>record(x)&&typeof x.title==='string'&&x.title.length<=100&&typeof x.category==='string'&&Number.isFinite(x.amount)&&x.amount>0&&x.amount<=100000000)))&&(!s.opening||(Number.isFinite(s.opening.amount)&&Math.abs(s.opening.amount)<=100000000&&typeof s.opening.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s.opening.date)&&!isNaN(Date.parse(s.opening.date))))&&Array.isArray(s.expenses)&&Array.isArray(s.sessions)&&s.expenses.length<=50000&&s.sessions.length<=50000&&['INR','USD','EUR','GBP','AED'].includes(s.currency)&&Number.isInteger(s.goal)&&s.goal>0&&s.goal<=1440&&s.expenses.every(x=>record(x)&&typeof x.title==='string'&&x.title.length<=100&&typeof x.category==='string'&&Number.isFinite(x.amount)&&x.amount>0&&x.amount<=100000000)&&s.sessions.every(x=>record(x)&&typeof x.subject==='string'&&x.subject.length<=80&&typeof x.topic==='string'&&x.topic.length<=160&&Number.isInteger(x.minutes)&&x.minutes>0&&x.minutes<=1440);}
function record(x){return x&&typeof x.id==='string'&&typeof x.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&!isNaN(Date.parse(x.date));}
let loadError=false;try{const saved=localStorage.getItem(key);if(saved){const parsed=JSON.parse(saved);if(!valid(parsed))throw Error();state=parsed;}}catch{loadError=true;}
function notice(t){$('notice').textContent=t;}
function persist(next){try{localStorage.setItem(key,JSON.stringify(next));state=next;render();return true;}catch{notice('Could not save. Browser storage may be blocked or full. Download a backup before leaving.');return false;}}
const money=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:state.currency}).format(n);
const sum=(a,k)=>a.reduce((n,x)=>n+x[k],0);
const matches=(x,r)=>r==='all'||(r==='today'?x.date===today():r==='custom'?(! $('range-start').value||x.date>=$('range-start').value)&&(!$('range-end').value||x.date<=$('range-end').value):x.date.startsWith(today().slice(0,7)));
function selectedTransactions(){const range=$('expense-range').value;return [...state.expenses.map(x=>({...x,_income:false})),...incomes().map(x=>({...x,_income:true}))].filter(x=>matches(x,range)).sort((a,b)=>b.date.localeCompare(a.date));}
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function list(items){const body=$('expense-list');body.replaceChildren();if(!items.length){const tr=node('tr'),td=node('td','No records in this date range.','empty');td.colSpan=7;tr.append(td);body.append(tr);return;}for(const x of items){const tr=node('tr');const cells=[x.date,x._income?'Income':'Expense',x.title,x.category,(x._income?'+ ':'− ')+money(x.amount),x.remark||''];for(const value of cells)tr.append(node('td',value));const action=node('td'),edit=node('button','Edit','remove'),del=node('button','Delete','remove');edit.type='button';edit.setAttribute('aria-label','Edit '+x.title);edit.onclick=()=>beginEdit(x);del.type='button';del.setAttribute('aria-label','Delete '+x.title);del.onclick=()=>{if(confirm('Delete this record?')){const prop=x._income?'incomes':'expenses';const next={...state,[prop]:(state[prop]||[]).filter(r=>r.id!==x.id)};if(editingTransaction?.id===x.id)cancelEdit();if(persist(next))notice('Record deleted.');}};action.append(edit,del);tr.append(action);body.append(tr);}}
function beginEdit(x){editingTransaction={id:x.id};$('transaction-type').value=x._income?'income':'expense';updateCategories(x.category);f.elements.date.value=x.date;f.elements.title.value=x.title;f.elements.amount.value=x.amount;f.elements.remark.value=x.remark||'';$('currency').value=state.currency;$('save-record').textContent='Update record';$('cancel-edit').hidden=false;f.scrollIntoView({behavior:'smooth',block:'center'});f.elements.title.focus();}
function cancelEdit(){editingTransaction=null;f.reset();$('transaction-type').value='expense';updateCategories();f.elements.date.value=today();$('currency').value=state.currency;$('save-record').textContent='Save record';$('cancel-edit').hidden=true;}
function render(){if(opening()){ $('balance-date').value=state.opening.date;$('balance-amount').value=state.opening.amount;const spent=sum(state.expenses.filter(x=>x.date>=state.opening.date&&x.date<=today()),'amount');$('balance-current').textContent=state.opening.date>today()?'Opening balance begins on '+state.opening.date:'Balance today: '+money(round(state.opening.amount+sum(incomes().filter(x=>x.date>=state.opening.date&&x.date<=today()),'amount')-spent));}else{$('balance-current').textContent='Set your opening balance to see your remaining balance.';}const exp=state.expenses.filter(x=>x.date===today()),range=$('expense-range').value,rows=selectedTransactions();$('spent-today').textContent=money(sum(exp,'amount'));$('spent-month').textContent=money(sum(state.expenses.filter(x=>matches(x,'month')),'amount'));$('income-month').textContent=money(sum(incomes().filter(x=>matches(x,'month')),'amount'));$('expense-total').textContent=rows.filter(x=>x._income).length+' income · '+rows.filter(x=>!x._income).length+' expenses';$('currency').value=state.currency;$('range-start-wrap').hidden=range!=='custom';$('range-end-wrap').hidden=range!=='custom';list(rows);}

const categoryOptions={"expense":["Food","Groceries","Dining out","Transport","Fuel","Rent","Utilities","Electricity","Water","Mobile & Internet","Shopping","Clothing","Education","Books & Stationery","Bills","Health","Medicines","Insurance","Subscriptions","Entertainment","Travel","Personal care","Fitness","Home maintenance","Family support","Gifts & Donations","Loan repayment","Bank fees","Taxes","Pets","Other"],"income":["Salary","Allowance","Freelance","Business income","Bonus","Commission","Overtime","Interest","Dividends","Rental income","Pension","Scholarship","Gift","Refund","Sale of items","Other"]};
const allCategories=type=>[...categoryOptions[type],...((state.customCategories||{})[type]||[])];
function updateCategories(selected){const select=$('transaction-category'),type=$('transaction-type').value==='income'?'income':'expense',options=allCategories(type);const nodes=options.map(text=>{const option=node('option',text);option.value=text;return option;});const add=node('option','+ Add your own category');add.value='__add__';select.replaceChildren(...nodes,add);select.value=typeof selected==='string'&&options.includes(selected)?selected:options[0];$('custom-category-fields').hidden=true;}
$('transaction-category').onchange=()=>{$('custom-category-fields').hidden=$('transaction-category').value!=='__add__';};
$('add-category').onclick=()=>{const type=$('transaction-type').value==='income'?'income':'expense',name=$('custom-category-name').value.trim(),existing=allCategories(type).find(x=>x.toLocaleLowerCase()===name.toLocaleLowerCase());if(!name){notice('Enter a category name.');return;}if(name.length>60){notice('Use up to 60 characters.');return;}if(existing){updateCategories(existing);notice('That category already exists.');return;}const custom=state.customCategories||{expense:[],income:[]};if(custom[type].length>=100){notice('You can save up to 100 custom categories per type.');return;}if(persist({...state,customCategories:{...custom,[type]:[...custom[type],name]}})){updateCategories(name);$('custom-category-name').value='';notice('Category saved.');}};
$('transaction-type').onchange=updateCategories;updateCategories();

const f=$('expense-form');f.elements.date.value=today();f.onsubmit=e=>{e.preventDefault();if(!f.reportValidity())return;const d=new FormData(f),editing=editingTransaction,r={id:editing?.id||crypto.randomUUID(),date:d.get('date'),title:d.get('title').trim(),remark:String(d.get('remark')||'').trim(),category:d.get('category'),amount:Number(d.get('amount'))};const isIncome=$('transaction-type').value==='income';const allowed=allCategories(isIncome?'income':'expense');if(!allowed.includes(r.category)){notice('Choose a category for this record type.');return;}if(!r.title){notice('Enter a description.');return;}const prop=isIncome?'incomes':'expenses';let next;if(editing){const expenses=state.expenses.filter(x=>x.id!==editing.id),incomes=(state.incomes||[]).filter(x=>x.id!==editing.id);next={...state,expenses,incomes,[prop]:[...((prop==='incomes'?incomes:expenses)),r]};}else next={...state,[prop]:[...(state[prop]||[]),r]};if(persist(next)){cancelEdit();notice(editing?'Record updated.':isIncome?'Income saved.':'Expense saved.');}};$('cancel-edit').onclick=cancelEdit;
$('currency').onchange=()=>{persist({...state,currency:$('currency').value});};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=node('a');a.href=url;a.download='daily-desk-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Backup downloaded.');};
$('import').onchange=async()=>{const file=$('import').files[0];if(!file)return;try{if(file.size>20000000)throw Error();const old=JSON.parse(await file.text());if(!valid(old))throw Error();const data={expenses:old.expenses||[],incomes:old.incomes||[],opening:old.opening,currency:old.currency,customCategories:old.customCategories,sessions:[],goal:120};if(confirm('Import money records and replace the records saved in this browser? Study tracker data from the old backup is not imported.')){if(persist(data)){updateCategories();notice('Old Daily Desk money records imported.');}}}catch{notice('This backup could not be read. Choose a valid Daily Desk JSON backup; backups from older versions are supported.');}$('import').value='';};
window.addEventListener('storage',e=>{if(e.key===key&&e.newValue){try{const s=JSON.parse(e.newValue);if(valid(s)){state=s;updateCategories();render();}}catch{}}});

$('balance-date').value=today();
$('balance-form').onsubmit=e=>{e.preventDefault();if(!$('balance-form').reportValidity())return;const amount=Number($('balance-amount').value),date=$('balance-date').value;if(!Number.isFinite(amount)||!date)return;if(persist({...state,opening:{amount,date}}))notice('Opening balance saved.');};
$('excel-export').onclick=()=>{const rows=selectedTransactions();if(!validDateRange())return;const table=[['Date','Type','Description','Category','Amount ('+state.currency+')','Remark'],...rows.map(x=>[x.date,x._income?'Income':'Expense',x.title,x.category,x._income?x.amount:-x.amount,x.remark||''])];download(new Blob([makeXlsx([{name:'Money records',rows:table}])],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'daily-desk-records-'+rangeFileName()+'.xlsx');notice('Excel file downloaded.');};
$('pdf-export').onclick=()=>{const rows=selectedTransactions();if(!validDateRange())return;download(new Blob([makeRecordsPdf(rows)],{type:'application/pdf'}),'daily-desk-records-'+rangeFileName()+'.pdf');notice('PDF file downloaded.');};
function validDateRange(){if($('expense-range').value==='custom'&&$('range-start').value&&$('range-end').value&&$('range-start').value>$('range-end').value){notice('The start date must be before the end date.');return false;}return true;}
function rangeFileName(){const range=$('expense-range').value;return range==='custom'?($('range-start').value||'start')+'-to-'+($('range-end').value||'end'):range==='month'?today().slice(0,7):range;}
function makeRecordsPdf(rows){const pageW=842,pageH=595,widths=[66,48,175,100,85,288],headers=['Date','Type','Description','Category','Amount ('+state.currency+')','Remark'];const pages=[];const ascii=value=>String(value??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/₹/g,'INR ').replace(/[^\x20-\x7E]/g,'?');const esc=value=>ascii(value).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');const text=(x,y,value,size=9,color='0.12 0.18 0.26')=>'BT /F1 '+size+' Tf '+color+' rg 1 0 0 1 '+x+' '+y+' Tm ('+esc(value)+') Tj ET\n';const clipped=(value,max)=>{const v=ascii(value);return v.length>max?v.slice(0,max-1)+'…'.replace('…','.') :v;};const perPage=18,count=Math.max(1,Math.ceil(rows.length/perPage));for(let pg=0;pg<count;pg++){let c='';c+=text(40,555,'Daily Desk — Money records',18,'0.09 0.20 0.38');const period=$('expense-range').value==='custom'?($('range-start').value||'Any date')+' to '+($('range-end').value||'Any date'):$('expense-range').value==='month'?'This month':$('expense-range').value==='today'?'Today':'All records';c+=text(40,535,'Date range: '+period+'   |   Currency: '+state.currency,10);c+='0.09 0.20 0.38 rg 40 500 762 24 re f\n';let x=40;headers.forEach((h,i)=>{c+='BT /F2 9 Tf 1 1 1 rg 1 0 0 1 '+(x+5)+' 508 Tm ('+esc(h)+') Tj ET\n';x+=widths[i];});const pageRows=rows.slice(pg*perPage,(pg+1)*perPage);pageRows.forEach((r,ri)=>{const y=476-ri*23;if(ri%2===1)c+='0.96 0.97 0.98 rg 40 '+(y-6)+' 762 23 re f\n';c+='0.86 0.89 0.92 RG 40 '+(y-6)+' m 802 '+(y-6)+' l S\n';const values=[r.date,r._income?'Income':'Expense',r.title,r.category,(r._income?'+ ':'- ')+state.currency+' '+Number(r.amount).toFixed(2),r.remark||''];let px=40;values.forEach((v,i)=>{const max=Math.max(7,Math.floor((widths[i]-10)/5.2));c+=text(px+5,y,clipped(v,max),8);px+=widths[i];});});c+=text(760,22,'Page '+(pg+1)+' of '+count,8,'0.35 0.39 0.44');pages.push(c);}const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids ['+pages.map((_,i)=>(5+i*2)+' 0 R').join(' ')+'] /Count '+pages.length+' >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>'];pages.forEach((content,i)=>{const pageId=5+i*2,streamId=pageId+1;objects.push('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+pageW+' '+pageH+'] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents '+streamId+' 0 R >>');objects.push('<< /Length '+content.length+' >>\nstream\n'+content+'endstream');});let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((obj,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+obj+'\nendobj\n';});const xref=pdf.length;pdf+='xref\n0 '+(objects.length+1)+'\n0000000000 65535 f \n';for(let i=1;i<offsets.length;i++)pdf+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';pdf+='trailer\n<< /Size '+(objects.length+1)+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';return pdf;}
$('expense-range').onchange=()=>{if($('expense-range').value==='custom'&&!$('range-start').value&&!$('range-end').value){$('range-start').value=today().slice(0,7)+'-01';$('range-end').value=today();}render();};$('range-start').onchange=render;$('range-end').onchange=render;
$('today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'long'});render();if(loadError)notice('Saved records could not be read. Restore a backup if you have one.');
})();

